// Accessible validation for supplier onboarding and programme forms.
export function isSupplierForm(form){return form.matches('#live-company,#company-form,[data-admin-form="company"],[data-admin-form="program"]');}
function fieldLabel(control){return control.labels?.[0]?.textContent.trim()||control.closest('.field')?.querySelector('label')?.textContent.trim()||control.name||'Поле';}
function messageFor(control){const v=control.validity;if(v.valueMissing)return control.type==='checkbox'?'Подтвердите этот пункт.':`Заполните поле «${fieldLabel(control)}».`;if(v.typeMismatch)return control.type==='email'?'Укажите корректный email.':'Укажите полный адрес страницы, например https://pina.market/#/legal/terms.';if(v.rangeUnderflow||v.rangeOverflow)return `Укажите значение от ${control.min} до ${control.max}.`;if(v.tooLong)return `Не более ${control.maxLength} символов.`;return 'Проверьте значение этого поля.';}
function clearErrors(form){form.querySelectorAll('[data-field-error],[data-validation-summary]').forEach(e=>e.remove());form.querySelectorAll('[aria-invalid="true"]').forEach(e=>{e.removeAttribute('aria-invalid');e.classList.remove('field-invalid');const refs=(e.getAttribute('aria-describedby')||'').split(/\s+/).filter(x=>x&&!x.endsWith('-error'));if(refs.length)e.setAttribute('aria-describedby',refs.join(' '));else e.removeAttribute('aria-describedby');});}
export function validateSupplierForm(form){
 clearErrors(form);const errors=[];let index=0;
 const add=(control,message,container)=>{if(!control.id)control.id=`${form.id||form.dataset.adminForm}-field-${index++}`;const id=control.id+'-error';control.classList.add('field-invalid');control.setAttribute('aria-invalid','true');control.setAttribute('aria-describedby',((control.getAttribute('aria-describedby')||'')+' '+id).trim());const error=document.createElement('small');error.id=id;error.dataset.fieldError='';error.className='field-error';error.textContent=message;(container||control.closest('.field')||control.closest('label')||control.parentElement).append(error);errors.push({control,message});};
 for(const control of form.querySelectorAll('input,select,textarea')){if(!control.willValidate)continue;if(!control.validity.valid){add(control,messageFor(control));continue;}if(control.required&&control.type!=='checkbox'&&control.type!=='radio'&&String(control.value).trim()===''){add(control,`Заполните поле «${fieldLabel(control)}».`);continue;}if(control.name==='rules'&&control.value&&!control.value.startsWith('https://')){add(control,'Укажите HTTPS-ссылку на оферту по картам.');continue;}if(control.name==='validity'){const m=control.value.trim().match(/^(\d+)\s*(?:день|дня|дней|дн\.?|days?)?(?:\s+со\s+дня\s+выпуска(?:\s+кода)?)?\.?$/iu);if(!m||Number(m[1])<1||Number(m[1])>365)add(control,'Укажите срок от 1 до 365 дней, например «180 дней».');}}
 for(const [selector,message] of [['[data-card-nominals]','Отметьте хотя бы один допустимый номинал карты.'],['[data-card-categories]','Отметьте хотя бы одну категорию товаров или услуг.']]){const group=form.querySelector(selector);if(group&&!group.querySelector('input:checked')){const first=group.querySelector('input');if(first&&!first.disabled)add(first,message,group);}}
 if(!errors.length)return true;
 const summary=document.createElement('div');summary.className='validation-summary';summary.dataset.validationSummary='';summary.setAttribute('role','alert');const title=document.createElement('strong');title.textContent='Проверьте заполнение формы';summary.append(title);const list=document.createElement('ul');for(const {control,message} of errors){const item=document.createElement('li'),link=document.createElement('a');link.href='#'+control.id;link.textContent=message;link.addEventListener('click',e=>{e.preventDefault();control.focus();control.scrollIntoView({block:'center',behavior:'smooth'});});item.append(link);list.append(item);}summary.append(list);form.prepend(summary);errors[0].control.focus();summary.scrollIntoView({block:'start',behavior:'smooth'});return false;
}
